def compare_versions(a: str, b: str) -> int:
    def parse(v: str) -> list[int]:
        v = v.strip()
        if v[:1] in ('v', 'V'):
            v = v[1:]
        return [int(p) for p in v.split('.')]

    pa, pb = parse(a), parse(b)
    n = max(len(pa), len(pb))
    pa += [0] * (n - len(pa))
    pb += [0] * (n - len(pb))
    if pa < pb:
        return -1
    if pa > pb:
        return 1
    return 0

