def split_csv_line(line: str) -> list[str]:
    fields = []
    buf = []
    in_quotes = False
    at_field_start = True
    i = 0
    n = len(line)
    while i < n:
        ch = line[i]
        if in_quotes:
            if ch == '"':
                if i + 1 < n and line[i + 1] == '"':
                    buf.append('"')
                    i += 2
                    continue
                in_quotes = False
            else:
                buf.append(ch)
        else:
            if ch == ',':
                fields.append(''.join(buf))
                buf = []
                at_field_start = True
                i += 1
                continue
            if ch == '"' and at_field_start:
                in_quotes = True
            else:
                buf.append(ch)
        at_field_start = False
        i += 1
    fields.append(''.join(buf))
    return fields
